@app.post("/api/jobs", operation_id="create_job_api_jobs_post")
async def create_job(request: Request, job: PublicJobCreateBody) -> dict[str, Any]:
    """Create a new job. **Dual-callable** (P4b):

    * Cockpit / user path → ``require_approved_user``; if ``body.project_id``
      is set, the caller must be at least an editor of that project; the
      submitted ``user_id`` is forced to ``caller.id`` so a malicious body
      can't create jobs attributed to someone else.
    * Agent path (delegation/session child jobs) → transport authentication via
      ``X-Internal-Key`` plus server-side user/project derivation from
      ``parent_job_id`` or ``thread_id``. Body identity/scope is never trusted.
      Originless internal HTTP calls are rejected; userless system children
      must still derive scope from an authoritative parent/thread.

    Creates a job with status 'created'. The automatic dispatcher provisions
    its workspace and assigns a ready agent; callers should monitor the job
    rather than manually assigning it.

    If ``project_id`` is set (directly or via the user's default project),
    the project's config and resources are inherited, while the root job still
    receives its own isolated repository. Subjobs branch within that root repo.
    """
    internal_call = is_internal_call(request)
    _strip_raw_officer_claim_context(job)
    caller: dict[str, Any] | None = None
    if not internal_call:
        caller = await require_approved_user(request, postgres_db)
        # Force user_id to caller; never honor body.user_id from a cockpit
        # caller (F2 pattern). Project membership is checked below once we
        # know the resolved project_id.
        job.user_id = str(caller["id"])
        _strip_public_job_reserved_markers(job)
        if job.project_id:
            await require_project_member(
                request, postgres_db, str(job.project_id), min_role="editor"
            )
    return await admit_job(
        command=job,
        actor=JobAdmissionActor(
            principal=caller,
            forwarded_user_id=request.headers.get("X-MCP-User-Id"),
        ),
        origin="internal_rest" if internal_call else "user_rest",
        dependencies=_job_admission_dependencies(
            lambda: _job_admission_scope_dependencies(request)
        ),
    )


@app.delete("/api/jobs/{job_id}")
async def delete_job(request: Request, job_id: str) -> dict[str, Any]:
    """Delete a job and its requirements.

    P4c: destructive. Caller must own the job OR be project-owner OR admin.
    Plain project membership is not enough — mirrors G3 sudo-authority gate.
    """
    caller, job = await require_job_access(request, postgres_db, job_id)
    require_srw_runtime(job)
    if not caller.get("is_admin"):
        is_job_owner = str(job.get("user_id") or "") == str(caller["id"])
        is_project_owner = False
        if not is_job_owner and job.get("project_id"):
            role = await postgres_db.get_user_role_in_project(
                str(job["project_id"]), str(caller["id"])
            )
            is_project_owner = role == "owner"
        if not (is_job_owner or is_project_owner):
            raise HTTPException(
                status_code=403,
                detail="Only the job owner, the project owner, or an admin may delete this job",
            )
    try:
        # A parent with surviving child rows can't be row-deleted anyway
        # (parent_job_id FK, no cascade) — fail fast BEFORE tearing down the
        # workspace, or the failed delete would leave the job alive with its
        # pod gone.
        if await postgres_db.has_child_jobs(job_id):
            raise HTTPException(
                status_code=409,
                detail="Job has child jobs; delete them first",
            )

        # A stateless saver is authorized by its run_queue generation, not by
        # the continued existence of the jobs row. Permanently fence that
        # generation and prove the canonical checkpoint thread empty before
        # workspace teardown; pruning after row deletion would let a live
        # predecessor recreate orphaned checkpoints.
        if job.get("execution_lane") == "stateless":
            prepared = await postgres_db.prepare_stateless_job_for_delete(job_id)
            if not prepared:
                raise HTTPException(
                    status_code=409,
                    detail="Stateless job changed while deletion was being prepared",
                )

        # Tear down workspace/VM resources while the row still exists — the
        # provisioners resolve them through the job's context, and once the
        # row is gone the lifecycle reconciler refuses to reap the pod
        # (no-bound-row is treated as in-flight provisioning; see
        # knowledge-history/done/deleted_job_orphans_workspace_pod.md).
        try:
            await _archive_and_cleanup_workspace(job_id)
        except Exception as exc:
            # Retain the owning row as the durable retry handle.  In
            # particular, a static Docker container may still hold a live
            # repo-scoped ssh-agent even after its lease is quarantined; and a
            # Pod/VM transport acknowledgement is not exact compute absence.
            # Deleting the row here would make either residue ownerless.
            logger.warning(
                "Workspace cleanup is incomplete for job %s: %s", job_id, exc
            )
            raise HTTPException(
                status_code=503,
                detail="Workspace authority retirement is incomplete",
            ) from exc
        # A deleted job can never be restored, so its S3 snapshots (including
        # the one release_workspace may have just captured) are garbage.
        if snapshot_service.is_available:
            try:
                await snapshot_service.delete_snapshot(job_id)
            except Exception as e:
                logger.warning(f"Snapshot cleanup failed for deleted job {job_id}: {e}")

        # Log-archive objects die with the job (retention:
        # knowledge-base/knowledge/features/job_log_archive.md). Re-fetch the row — keys may have
        # been stamped after this handler fetched it.
        if snapshot_service.is_available:
            try:
                fresh = await postgres_db.get_job(job_id) or {}
                ctx = fresh.get("context") or {}
                if isinstance(ctx, str):
                    ctx = json.loads(ctx)
                for key in ctx.get("log_archive_keys") or []:
                    await snapshot_service.delete_blob(str(key))
            except Exception as e:
                logger.warning(
                    f"Log archive cleanup failed for deleted job {job_id}: {e}"
                )

        # Clean up Gitea repo/branch. Root repository deletion is a security
        # boundary: if Gitea is unavailable, retain the job row as the durable
        # retry handle instead of orphaning a still-usable deploy key.
        repo_name = job.get("repo_name")
        branch_name = job.get("branch_name")
        isolated_repo_name = f"job-{str(job.get('id') or job_id)[:8]}"
        if repo_name or branch_name:
            if job.get("parent_job_id") and branch_name and repo_name:
                # Subjob: delete the branch (no-op if already merged and deleted)
                if gitea_client.is_initialized:
                    await gitea_client.delete_branch(repo_name, branch_name)
            elif repo_name == isolated_repo_name:
                # New root-job model: this repo belongs to exactly this job.
                if not await revoke_and_delete_managed_repository(
                    postgres_db, gitea_client, repo_name
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Repository credential revocation is retryable",
                    )
            elif job.get("project_id") and branch_name:
                # Legacy project job: the repo is shared. Never delete it from a
                # job endpoint, even when repo_name is stamped on the row (which
                # newer legacy rows are). Delete only this job's branch.
                legacy_repo_name = repo_name
                if not legacy_repo_name:
                    repos = await postgres_db.get_project_repositories(
                        str(job["project_id"]), role="jobs"
                    )
                    legacy_repo_name = repos[0]["name"] if repos else None
                if legacy_repo_name and branch_name != "main":
                    await gitea_client.delete_branch(legacy_repo_name, branch_name)
            elif repo_name and not job.get("project_id"):
                # Pre-migration loose root job: its non-project repo is private
                # to the job even if it predates the deterministic short name.
                if not await revoke_and_delete_managed_repository(
                    postgres_db, gitea_client, repo_name
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Repository credential revocation is retryable",
                    )
        # Fence delayed vector writers and prune this job's scope atomically.
        # The destination tombstone survives the application row, so a late
        # extraction cannot recreate orphaned memories after DELETE succeeds.
        try:
            async with vector_db.acquire() as conn:
                await conn.execute(
                    "SELECT retire_job_vector_scope($1::uuid)", UUID(job_id)
                )
        except Exception as e:
            logger.warning("Vector retirement is incomplete for job %s: %s", job_id, e)
            raise HTTPException(
                status_code=503,
                detail="Job vector cleanup is incomplete; retry deletion",
            ) from e

        if job.get("execution_lane") == "stateless":
            delete_result = await postgres_db.delete_job(
                job_id,
                prepared_stateless=True,
                deletion_actor_user_id=str(caller["id"]),
                deletion_reason="authorized_api_delete",
                return_claim_state=True,
            )
        else:
            # Pinned deletion keeps its historical collaborator signature and
            # behavior; only stateless checkpoints need the queue fence above.
            delete_result = await postgres_db.delete_job(
                job_id,
                deletion_actor_user_id=str(caller["id"]),
                deletion_reason="authorized_api_delete",
                return_claim_state=True,
            )
        # ``return_claim_state`` is implemented by PostgresDB. Tolerating the
        # historical boolean here keeps narrow test collaborators and rolling
        # application adapters safe, but only the mapping can assert a claim.
        if isinstance(delete_result, dict):
            success = bool(delete_result.get("deleted"))
            claim_retained = bool(delete_result.get("ticket_claim_retained"))
        else:
            success = bool(delete_result)
            claim_retained = False
        if not success:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")
        await _resolve_job_notifications(job_id, user=caller, hook="delete")
        return {
            "status": "deleted",
            "ticket_claim_retained": claim_retained,
            "ticket_rearmed": False,
            "message": (
                "Job deleted. Its backlog-ticket claim remains durable; "
                "deletion does not re-arm the ticket."
                if claim_retained
                else "Job deleted. This job had no durable backlog-ticket claim."
            ),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/jobs/{job_id}/subjob-merge")
async def subjob_merge(request: Request, job_id: str) -> dict[str, Any]:
    """Graft a completed subjob's output/ onto its parent's branch.
    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips this
    path.

    Called by the agent after a subjob completes (autonomy=full auto-completion).
    Grafts the subjob's output/ onto the parent as a namespaced outputs/ folder.
    """
    await require_internal(request)
    try:
        job = await postgres_db.get_job(job_id)
        if not job:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")

        if not job.get("parent_job_id"):
            raise HTTPException(
                status_code=400,
                detail="Only subjobs (with parent_job_id) can be grafted",
            )

        result = await subjob_output_operations.graft_subjob_output(
            job_id, dependencies=_subjob_output_dependencies()
        )
        if result is None:
            return {"status": "skipped", "reason": "no branch/repo configured"}

        return {"job_id": job_id, **result}

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Squash merge failed for subjob {job_id}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e)) from e


async def _cascade_cancel_to_children(job_id: str) -> bool:
    """Cancel descendant jobs and finish previously cancelled child retirement.

    Fetches the full descendant tree (recursive), signals processing agents
    to stop, publishes cancellation, and cleans up VMs/containers.
    """
    children = await postgres_db.get_descendant_jobs(job_id, include_cancelled=True)
    if not children:
        return True
    native_settled = True
    for child in children:
        if not uses_srw_runtime(child):
            native_settled = (
                await _manifest_execution_service().cancel(str(child["id"]))
                and native_settled
            )
    children = [child for child in children if uses_srw_runtime(child)]
    if not children:
        return native_settled

    # Signal processing agents concurrently
    async def _signal_cancel(child: dict) -> bool:
        child_id = str(child["id"])
        agent_id = child.get("assigned_agent_id")
        if child["status"] != "processing":
            return True
        if not agent_id:
            return False
        target = await _prepare_pinned_job_mutation_target(
            agent_id=str(agent_id),
            job_id=child_id,
            require_idle=False,
        )
        if target is None:
            return False
        agent_url = (
            f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}/job/cancel"
        )
        try:
            async with httpx.AsyncClient(timeout=130.0) as client:
                response = await client.post(
                    agent_url,
                    json={
                        "reason": f"Parent job {job_id} cancelled",
                        "recipient": target.recipient.model_dump(mode="json"),
                    },
                )
            return response.status_code == 200
        except Exception as e:
            logger.warning(f"Could not reach agent to cancel child {child_id}: {e}")
            return False

    async def _cleanup_child(child: dict) -> bool:
        child_id = str(child["id"])
        try:
            await _archive_and_cleanup_workspace(child_id)
        except Exception as exc:
            logger.warning("Workspace cleanup failed for child %s: %s", child_id, exc)
            return False
        return True

    pinned_children = [c for c in children if c.get("execution_lane") != "stateless"]
    stateless_children = [c for c in children if c.get("execution_lane") == "stateless"]

    pinned_settled = True

    async def _cancel_pinned_child(child: dict) -> bool:
        child_id = str(child["id"])
        won = await postgres_db.linearize_pinned_cancel(
            child_id,
            expected_status=str(child.get("status") or ""),
            completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
        )
        if not won:
            refreshed = await postgres_db.get_job(child_id)
            if not refreshed or refreshed.get("status") in (
                "completed",
                "failed",
            ):
                return True
            if refreshed.get("status") != "cancelled":
                return False
            # A previous caller may have committed cancellation and died
            # before external retirement.  The terminal row remains the
            # retry owner; never treat status alone as cleanup success.
            return await _cleanup_child(refreshed)
        signal_result, cleanup_result = await asyncio.gather(
            _signal_cancel(child),
            _cleanup_child(child),
            return_exceptions=True,
        )
        if isinstance(signal_result, BaseException):
            logger.warning(
                "Cascade cancellation signal raised for child %s",
                child_id,
                exc_info=(
                    type(signal_result),
                    signal_result,
                    signal_result.__traceback__,
                ),
            )
        return signal_result is True and cleanup_result is True

    pinned_results = await asyncio.gather(
        *[_cancel_pinned_child(c) for c in pinned_children],
        return_exceptions=True,
    )
    for child, result in zip(pinned_children, pinned_results, strict=True):
        if result is True:
            continue
        pinned_settled = False
        logger.error(
            "Cascade cancellation stood down for pinned child %s because "
            "another completion/control owner won",
            child.get("id"),
        )

    async def _cancel_stateless_child(child: dict) -> bool:
        child_id = str(child["id"])
        cancelled, _queue_closed = await postgres_db.cancel_stateless_job(
            child_id, **_completion_control_boundary.dispatch_guard_kwargs()
        )
        if cancelled:
            return await _wait_for_stateless_cancel_settle(child_id)
        refreshed = await postgres_db.get_job(child_id)
        if not refreshed:
            return True
        if refreshed.get("status") in ("completed", "failed"):
            return True
        if refreshed.get("status") != "cancelled":
            return False
        refreshed_context = refreshed.get("context") or {}
        if isinstance(refreshed_context, str):
            try:
                refreshed_context = json.loads(refreshed_context)
            except (TypeError, ValueError):
                refreshed_context = {}
        if refreshed_context.get("_stateless_cancel_cleanup_pending") is True:
            return await _wait_for_stateless_cancel_settle(child_id)
        return True

    stateless_results = await asyncio.gather(
        *[_cancel_stateless_child(c) for c in stateless_children],
        return_exceptions=True,
    )
    stateless_settled = True
    for child, result in zip(stateless_children, stateless_results, strict=True):
        if result is True:
            continue
        stateless_settled = False
        if isinstance(result, BaseException):
            logger.error(
                "Cascade cancellation could not settle stateless child %s",
                child.get("id"),
                exc_info=(type(result), result, result.__traceback__),
            )
        else:
            logger.error(
                "Cascade cancellation timed out with stateless child %s still live",
                child.get("id"),
            )

    logger.info(f"Cascade-cancelled {len(children)} descendant(s) of job {job_id}")
    return pinned_settled and stateless_settled and native_settled


async def _cascade_pause_to_children(job_id: str) -> None:
    """Pause all processing descendant jobs of a parent.

    Only actively-processing children are signaled and paused in DB.
    Non-processing children (created, waiting) are implicitly held by
    the dispatcher's ancestor guard.
    """
    children = await postgres_db.get_descendant_jobs(job_id)
    processing = [
        c for c in children if c["status"] == "processing" and uses_srw_runtime(c)
    ]
    if not processing:
        return
    pinned_processing = [
        c for c in processing if c.get("execution_lane") != "stateless"
    ]
    stateless_processing = [
        c for c in processing if c.get("execution_lane") == "stateless"
    ]

    async def _signal_pause(
        child: dict,
        *,
        already_paused: bool = False,
        require_positive_quiescence: bool = False,
    ) -> bool:
        child_id = str(child["id"])
        agent_id = child.get("assigned_agent_id")
        if not agent_id and not require_positive_quiescence:
            return True
        if agent_id:
            target = await _prepare_pinned_job_mutation_target(
                agent_id=str(agent_id),
                job_id=child_id,
                require_idle=False,
            )
            if target is None:
                return False
            else:
                agent_url = (
                    f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                    "/job/pause"
                )
                try:
                    async with httpx.AsyncClient(timeout=130.0) as client:
                        response = await client.post(
                            agent_url,
                            json={
                                "recipient": target.recipient.model_dump(mode="json")
                            },
                        )
                except Exception as e:
                    logger.warning(
                        f"Could not reach agent to pause child {child_id}: {e}"
                    )
                    if require_positive_quiescence:
                        return False
                else:
                    if response.status_code != 200:
                        logger.warning(
                            "Cascade pause for child %s was not positively "
                            "acknowledged (%s)%s",
                            child_id,
                            response.status_code,
                            (
                                "; retaining bounded control hold"
                                if require_positive_quiescence
                                else ""
                            ),
                        )
                        if require_positive_quiescence:
                            return False

        if not already_paused:
            await postgres_db.pause_job(child_id)
        return True

    if COMPLETION_COMMANDS_ENABLED:

        async def _linearize_and_signal_pause(child: dict) -> None:
            child_id = str(child["id"])
            try:
                pause_claim = await _completion_control_boundary.claim_pause(
                    child_id,
                    source="cascade_pause",
                    expected_agent_id=(
                        str(child["assigned_agent_id"])
                        if child.get("assigned_agent_id")
                        else None
                    ),
                )
            except HTTPException:
                logger.info(
                    "Cascade pause: child %s changed or is controlled; "
                    "skipping external pause",
                    child_id,
                )
                return
            quiescent = await _signal_pause(
                child,
                already_paused=True,
                require_positive_quiescence=True,
            )
            if quiescent:
                await _completion_control_boundary.abort(pause_claim)
            else:
                logger.warning(
                    "Cascade pause: retaining child %s control hold until "
                    "bounded expiry",
                    child_id,
                )

        await asyncio.gather(
            *[_linearize_and_signal_pause(c) for c in pinned_processing],
            return_exceptions=True,
        )
    else:
        await asyncio.gather(
            *[_signal_pause(c) for c in pinned_processing],
            return_exceptions=True,
        )
    for child in stateless_processing:
        await postgres_db.pause_stateless_job(
            str(child["id"]), **_completion_control_boundary.dispatch_guard_kwargs()
        )

    logger.info(
        f"Cascade-paused {len(processing)} processing descendant(s) of job {job_id}"
    )


async def _wait_for_stateless_cancel_settle(
    job_id: str,
    *,
    timeout_seconds: float = 130.0,
    poll_seconds: float = 0.5,
) -> bool:
    """Wait for a cancelled worker owner to teardown, then prune/archive.

    The status write is the preemption signal and must happen first. A live
    holder discovers it on renewal, tears down local/tmux ownership, then
    closes its exact queue lease. A killed holder is reclaimed within the
    queue TTL/reaper horizon. Only after that boundary is it safe to delete the
    shared checkpoint and workspace underneath the former owner.
    """
    deadline = asyncio.get_running_loop().time() + max(0.0, timeout_seconds)
    while True:
        try:
            async with postgres_db.stateless_cancel_cleanup_lock(
                job_id
            ) as cleanup_owner:
                if not cleanup_owner:
                    settled = False
                else:
                    cleanup_pending = (
                        await postgres_db.stateless_cancel_cleanup_pending(job_id)
                    )
                    if cleanup_pending is False:
                        # A prior owner already cleared the durable marker (or
                        # permanent DELETE removed the row). Never repeat the
                        # destructive workspace cleanup after Resume can run.
                        return True
                    if cleanup_pending is None:
                        settled = False
                    else:
                        settled = await postgres_db.finalize_cancelled_stateless_job(
                            job_id
                        )
                    if settled:
                        workspace_clean = True
                        try:
                            await _archive_and_cleanup_workspace(job_id)
                        except Exception as exc:
                            workspace_clean = False
                            logger.warning(
                                "Workspace cleanup failed for cancelled stateless "
                                "job %s: %s",
                                job_id,
                                exc,
                            )
                        if workspace_clean:
                            cleanup_completed = (
                                await postgres_db.complete_stateless_cancel_cleanup(
                                    job_id
                                )
                            )
                            if cleanup_completed:
                                return True
                            settled = False
                        else:
                            # Keep the durable Resume block until workspace teardown
                            # has actually returned successfully. Clearing it after an
                            # exception would let a new claim attach while cancellation's
                            # destructive cleanup is only half complete.
                            settled = False
        except Exception:
            logger.warning(
                "Stateless cancel settle check failed for job %s; retrying",
                job_id,
                exc_info=True,
            )
            settled = False

        remaining = deadline - asyncio.get_running_loop().time()
        if remaining <= 0:
            return False
        await asyncio.sleep(min(max(0.01, poll_seconds), remaining))


@app.put("/api/jobs/{job_id}/cancel")
async def cancel_job(request: Request, job_id: str) -> dict[str, str]:
    """Cancel a running job. **Dual-callable** (P4b): cockpit user with job
    access (``require_job_access``) OR agent with valid ``X-Internal-Key``
    (agent's `cancel_job` tool path).

    If the job is assigned to an agent, this will also send a cancel request
    to the agent pod.
    """
    _, job = await require_internal_or_job_access(request, postgres_db, job_id)
    return await _cancel_job_internal(job_id, job=job)


async def _cancel_job_internal(job_id: str, *, job: dict) -> dict[str, str]:
    """Cancel already-authorized work through its existing runtime fences."""
    if getattr(postgres_db, "manifests_ready", False) is True:
        if await _manifest_execution_service().cancel(job_id):
            return {"status": "cancelled"}
    pinned_cancel_committed = False

    try:
        if job.get("execution_lane") == "stateless":
            success, _queue_closed = await postgres_db.cancel_stateless_job(
                job_id, **_completion_control_boundary.dispatch_guard_kwargs()
            )
            if not success:
                refreshed = await postgres_db.get_job(job_id)
                if refreshed and refreshed.get("execution_lane") == "pinned":
                    # The defensive VM repair may have won the queue lock and
                    # moved this legacy row after our initial lane read. Fall
                    # through to the established pinned cancellation path.
                    job = refreshed
                elif (
                    refreshed
                    and (refreshed.get("context") or {}).get(
                        "_stateless_delete_pending"
                    )
                    is True
                ):
                    raise HTTPException(
                        status_code=409,
                        detail="Job deletion is already in progress",
                    )
                elif (
                    refreshed
                    and refreshed.get("status") not in ("completed", "cancelled")
                    and _completion_control_boundary.active_claim(refreshed)
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_boundary.claim_detail(refreshed),
                    )
                elif not refreshed or refreshed.get("status") != "cancelled":
                    raise HTTPException(
                        status_code=400,
                        detail=(
                            "Job cannot be cancelled (already completed or cancelled)"
                        ),
                    )

            if job.get("execution_lane") == "stateless":
                # Publish descendant cancellation before any root-workspace
                # teardown. Stateless children can share this exact parent pod;
                # waiting below must include their live holders or cleanup could
                # pull the workspace out from under a still-running critic/scholar.
                descendants_settled = await _cascade_cancel_to_children(job_id)

                if descendants_settled:
                    # The current token remains live so renewal can return the
                    # cancelled status. Wait through the same bounded cooperative
                    # stop horizon as the pinned cancel route, then clean up only
                    # after the exact holder has closed (or the reaper reconciled)
                    # the queue row.
                    settled = await _wait_for_stateless_cancel_settle(job_id)
                    if not settled:
                        logger.error(
                            "Stateless cancel cleanup timed out for job %s; terminal "
                            "workspace lifecycle remains the teardown backstop",
                            job_id,
                        )
                else:
                    logger.error(
                        "Stateless cancel left root workspace %s intact because a "
                        "descendant worker was not proven quiescent",
                        job_id,
                    )
                    raise HTTPException(
                        status_code=503,
                        detail=(
                            "Descendant workspace authority retirement is incomplete"
                        ),
                    )

                job["status"] = "cancelled"
                try:
                    await subjob_completion_operations.handle_scholar_completion(
                        job,
                        [],
                        dependencies=_scholar_completion_dependencies(),
                    )
                except Exception as exc:
                    logger.warning(
                        "Error handling scholar cancellation for %s: %s", job_id, exc
                    )
                await maybe_wake_session(postgres_db, job_id, "cancelled")
                _kick_session_wake_drain(postgres_db)
                _trigger_dispatch()
                await _resolve_job_notifications(job_id, user=None, hook="cancel")
                return {"status": "cancelled"}

        if job.get("execution_lane") == "pinned":
            # Linearize the user's cancellation before agent/VM/workspace I/O.
            # Terminal workspace retirement requires this status in both
            # completion-command modes. The finalizer must also observe it
            # before external quiescence. Checkpoint pruning stays below.
            pinned_cancel_committed = await postgres_db.linearize_pinned_cancel(
                job_id,
                expected_status=str(job.get("status") or ""),
                completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
            )
            if not pinned_cancel_committed:
                refreshed = await postgres_db.get_job(job_id)
                if (
                    COMPLETION_COMMANDS_ENABLED
                    and refreshed
                    and refreshed.get("status") not in ("completed", "cancelled")
                    and _completion_control_boundary.active_claim(refreshed)
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_boundary.claim_detail(refreshed),
                    )
                if not refreshed or refreshed.get("status") != "cancelled":
                    raise HTTPException(
                        status_code=400,
                        detail="Job cannot be cancelled (already completed or cancelled)",
                    )

                # A prior cancellation may have committed before cleanup
                # failed. Its retry still owns the deferred checkpoint prune.
                pinned_cancel_committed = True

        # If job is assigned to an agent, send cancel request to agent pod
        assigned_agent_id = job.get("assigned_agent_id")
        if assigned_agent_id:
            target = await _prepare_pinned_job_mutation_target(
                agent_id=str(assigned_agent_id),
                job_id=job_id,
                require_idle=False,
            )
            if target is not None:
                agent_url = (
                    f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                    "/job/cancel"
                )
                try:
                    # 130s timeout: agent tries cooperative stop for up to 120s,
                    # then falls back to hard kill. We wait slightly longer.
                    async with httpx.AsyncClient(timeout=130.0) as client:
                        response = await client.post(
                            agent_url,
                            json={
                                "reason": "Cancelled via cockpit",
                                "recipient": target.recipient.model_dump(mode="json"),
                            },
                        )
                        if response.status_code == 200:
                            resp_data = response.json()
                            if resp_data.get("graceful", True):
                                logger.info(
                                    f"Agent confirmed graceful cancel for job {job_id}"
                                )
                            else:
                                logger.warning(
                                    f"Agent hard-killed job {job_id} after cooperative timeout"
                                )
                        elif response.status_code == 408:
                            logger.warning(
                                f"Agent cancel timed out for job {job_id} — may still stop after current node"
                            )
                        else:
                            logger.warning(
                                f"Agent cancel returned {response.status_code}: {response.text}"
                            )
                except Exception as e:
                    # Agent might be unreachable — still cancel in DB
                    logger.warning(f"Could not reach agent to cancel job {job_id}: {e}")

        # Descendants can share the root Pod/VM/Docker namespace. Quiesce and
        # terminalize every child before the root performs namespace-wide
        # repository-agent retirement or compute deletion.
        if not await _cascade_cancel_to_children(job_id):
            raise HTTPException(
                status_code=503,
                detail="Descendant workspace authority retirement is incomplete",
            )

        # Archive workspace (snapshot to S3) and clean up VM/container
        try:
            await _archive_and_cleanup_workspace(job_id)
        except Exception as exc:
            # ``linearize_pinned_cancel`` may already have published the
            # terminal status.  Keep the row as the durable retry owner and
            # make the caller retry cleanup; the Docker lifecycle sweep also
            # owns any exact static-workspace residue.
            logger.warning(
                "Workspace cleanup remains pending for cancelled job %s: %s",
                job_id,
                exc,
            )
            raise HTTPException(
                status_code=503,
                detail="Workspace authority retirement is incomplete",
            ) from exc

        success = await postgres_db.cancel_job(job_id)
        if not success:
            # Agent may have already set status to 'cancelled' before we got here
            refreshed = await postgres_db.get_job(job_id)
            if refreshed and refreshed.get("status") == "cancelled":
                logger.info(f"Job {job_id} already cancelled (agent beat us to it)")
            else:
                raise HTTPException(
                    status_code=400,
                    detail="Job cannot be cancelled (already completed or cancelled)",
                )
        if pinned_cancel_committed:
            try:
                await postgres_db.delete_checkpoint_thread(job_id)
            except Exception as exc:
                logger.debug("checkpoint prune skipped for %s: %s", job_id, exc)

        # If this was a scholar, unblock the parent job
        job["status"] = "cancelled"
        try:
            await subjob_completion_operations.handle_scholar_completion(
                job,
                [],
                dependencies=_scholar_completion_dependencies(),
            )
        except Exception as e:
            logger.warning(f"Error handling scholar cancellation for {job_id}: {e}")

        # A session cancelling its own job does not need telling — but a user
        # cancelling from the cockpit does, and the session can't distinguish
        # the two from a status column. One cheap turn either way; the cost of
        # NOT sending is a session that waits on a job that will never report.
        # (Cascade-cancelled children are never session-created — they carry a
        # parent_job_id, so create_job withholds the backref — which is why
        # _cascade_cancel_to_children needs no hook of its own.)
        await maybe_wake_session(postgres_db, job_id, "cancelled")
        _kick_session_wake_drain(postgres_db)

        # Agent is being freed — trigger dispatcher for queued jobs
        _trigger_dispatch()
        await _resolve_job_notifications(job_id, user=None, hook="cancel")

        return {"status": "cancelled"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.put("/api/jobs/{job_id}/pause")
async def pause_job(request: Request, job_id: str) -> dict[str, str]:
    """Pause a running job. **Dual-callable** (P4b): cockpit user with
    job access OR agent with ``X-Internal-Key`` (`pause_job` tool).

    If the job is assigned to an agent, sends a graceful pause request
    to the agent pod. The agent finishes its current graph node, saves
    the checkpoint, and becomes available for new work.

    The paused job re-enters the dispatch queue and will be auto-resumed
    when an agent becomes available.
    """
    _, job = await require_internal_or_job_access(request, postgres_db, job_id)
    require_srw_runtime(job)
    try:
        if job["status"] != "processing":
            raise HTTPException(
                status_code=400,
                detail=f"Job cannot be paused (status: {job['status']})",
            )

        if job.get("execution_lane") == "stateless":
            success = await postgres_db.pause_stateless_job(
                job_id, **_completion_control_boundary.dispatch_guard_kwargs()
            )
            if not success:
                refreshed = await postgres_db.get_job(job_id)
                if _completion_control_boundary.active_claim(refreshed):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_boundary.claim_detail(refreshed),
                    )
                raise HTTPException(
                    status_code=400,
                    detail="Job cannot be paused (status may have changed)",
                )
            await maybe_wake_session(postgres_db, job_id, "paused")
            await _cascade_pause_to_children(job_id)
            return {"status": "paused", "job_id": job_id}

        # Flag-on publishes paused + an exact marker before old-executor I/O.
        # The marker remains on ambiguous timeout/failure so no successor can
        # be dispatched into a still-running agent or stale VM freeze.
        pause_claim = (
            await _completion_control_boundary.claim_pause(
                job_id,
                source="public_pause",
                expected_agent_id=(
                    str(job["assigned_agent_id"])
                    if job.get("assigned_agent_id")
                    else None
                ),
            )
            if COMPLETION_COMMANDS_ENABLED
            else None
        )
        release_pause_claim = False
        try:
            assigned_agent_id = job.get("assigned_agent_id")
            agent_quiescent = not assigned_agent_id
            if assigned_agent_id:
                target = await _prepare_pinned_job_mutation_target(
                    agent_id=str(assigned_agent_id),
                    job_id=job_id,
                    require_idle=False,
                )
                if target is None:
                    agent_quiescent = False
                else:
                    agent_url = (
                        f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                        "/job/pause"
                    )
                    try:
                        async with httpx.AsyncClient(timeout=130.0) as client:
                            response = await client.post(
                                agent_url,
                                json={
                                    "recipient": target.recipient.model_dump(
                                        mode="json"
                                    )
                                },
                            )
                        if response.status_code == 200:
                            agent_quiescent = True
                            logger.info(f"Agent confirmed pause for job {job_id}")
                        elif response.status_code == 408:
                            logger.warning(
                                "Pause timed out for job %s; retaining control "
                                "hold until bounded expiry",
                                job_id,
                            )
                        else:
                            logger.warning(
                                f"Agent pause returned {response.status_code}: "
                                f"{response.text}"
                            )
                    except httpx.TimeoutException:
                        logger.warning(
                            f"Timeout sending pause to agent for job {job_id}"
                        )
                    except Exception as e:
                        logger.warning(
                            f"Could not reach agent to pause job {job_id}: {e}"
                        )

            if pause_claim is None:
                success = await postgres_db.pause_job(job_id)
                if not success:
                    raise HTTPException(
                        status_code=400,
                        detail="Job cannot be paused (status may have changed)",
                    )
            release_pause_claim = agent_quiescent
        finally:
            if pause_claim is not None and release_pause_claim:
                await _completion_control_boundary.abort(pause_claim)
            elif pause_claim is not None:
                logger.warning(
                    "Pause control hold retained for job %s after ambiguous "
                    "quiescence; bounded expiry will release it",
                    job_id,
                )

        # 'paused' is officer-only inside maybe_wake_session — it never enters
        # the ordinary jobs outbox (risk 6), but a paused job is exactly what
        # the project's officer exists to notice.
        await maybe_wake_session(postgres_db, job_id, "paused")

        # Cascade pause to processing child/subjobs
        await _cascade_pause_to_children(job_id)

        return {"status": "paused", "job_id": job_id}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.put("/api/jobs/{job_id}/agent-release")
async def agent_release_job(
    request: Request,
    job_id: str,
    agent_id: str | None = None,
    lease_token: int | None = None,
) -> dict[str, str]:
    """Agent-initiated job release (no agent callback). **Internal** (P4b)
    — requires ``X-Internal-Key``. Ingress strips this path.

    Called by an agent that is shutting down or otherwise releasing a job
    it was working on. Unlike the regular pause endpoint, this does NOT try to
    contact the agent pod (since the caller *is* the agent). A leased pinned
    job is handed to the authoritative expiry sweep, which advances durable
    redispatch accounting; only a genuine pre-lease NULL-lease row is paused
    here directly. Stateless work retains its queue-token release contract.
    """
    await require_internal(request)
    try:
        job = await postgres_db.get_job(job_id)
        if job is not None:
            require_srw_runtime(job)
        lease_recovery_pending = False
        if not job:
            success = False
        elif (
            job.get("execution_lane", "pinned") == "pinned"
            and job.get("lease_expires_at") is not None
        ):
            if COMPLETION_COMMANDS_ENABLED and agent_id is None:
                raise HTTPException(
                    status_code=409,
                    detail="Agent release does not identify the assigned agent",
                )
            success = await postgres_db.route_pinned_agent_release_to_lease_recovery(
                job_id,
                completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
                expected_agent_id=agent_id,
            )
            lease_recovery_pending = success
        elif not COMPLETION_COMMANDS_ENABLED:
            success = await postgres_db.pause_job(job_id)
        else:
            if job.get("execution_lane") == "stateless":
                if lease_token is None:
                    raise HTTPException(
                        status_code=409,
                        detail="Agent release does not hold the worker lease",
                    )
                success = await postgres_db.pause_stateless_job(
                    job_id,
                    completion_commands_enabled=True,
                    expected_lease_token=lease_token,
                )
            else:
                if agent_id is None:
                    raise HTTPException(
                        status_code=409,
                        detail="Agent release does not identify the assigned agent",
                    )
                success = await postgres_db.pause_job(
                    job_id,
                    completion_commands_enabled=True,
                    expected_agent_id=agent_id,
                )
        if not success:
            refreshed = (
                await postgres_db.get_job(job_id)
                if COMPLETION_COMMANDS_ENABLED
                else None
            )
            if _completion_control_boundary.active_claim(refreshed):
                raise HTTPException(
                    status_code=409,
                    detail=_completion_control_boundary.claim_detail(refreshed),
                )
            if (
                COMPLETION_COMMANDS_ENABLED
                and refreshed
                and refreshed.get("status") == "processing"
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Job ownership changed before agent release",
                )
            raise HTTPException(
                status_code=400,
                detail="Job cannot be paused (not found or status changed)",
            )
        if lease_recovery_pending:
            logger.info(
                "Agent released leased job %s — lease expiry recovery pending",
                job_id,
            )
            return {"status": "lease_recovery_pending", "job_id": job_id}
        logger.info(f"Agent released job {job_id} — paused for reassignment")
        _trigger_dispatch()
        return {"status": "paused", "job_id": job_id}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


# =============================================================================
# VM Lifecycle Endpoints (optional — requires NATS)
# =============================================================================


@app.post("/api/vms")
async def create_vm(request: Request, body: VMCreateRequest) -> dict[str, Any]:
    """Create a VM for a job.

    **P4f** — gated by `require_job_access` on ``body.job_id``. VM
    provisioning is job-scoped, so callers must already be able to see
    the job. Admins (and project members) inherit access via the gate.

    Uses NATS (cross-cluster) or direct Kubernetes API (same-cluster).
    Returns 503 if no VM provisioning backend is available.
    """
    _caller, job = await require_job_access(request, postgres_db, body.job_id)
    try:
        assigned_backend = resolve_workspace_contract(job).assigned_backend
    except WorkspaceContractError as exc:
        raise HTTPException(
            status_code=409,
            detail={"code": exc.code, "message": exc.detail},
        ) from exc
    if assigned_backend != "vm":
        raise HTTPException(
            status_code=409,
            detail={
                "code": "workspace_backend_conflict",
                "message": "Job is not assigned to the VM workspace tier",
                "assigned_backend": assigned_backend,
            },
        )
    if not vm_provisioner.is_available:
        raise HTTPException(
            status_code=503, detail="VM provisioning not available (no NATS or K8s)"
        )

    success = await vm_provisioner.create_vm(
        job_id=body.job_id,
        agent_config=body.agent_config,
        vm_image=body.vm_image,
        cpu_cores=body.cpu_cores,
        memory=body.memory,
        description=body.description,
    )
    if not success:
        raise HTTPException(status_code=500, detail="Failed to create VM")

    return {
        "status": "provisioning",
        "job_id": body.job_id,
        "mode": vm_provisioner.mode,
    }


@app.get("/api/vms")
async def list_vms(request: Request) -> list[dict[str, Any]]:
    """List jobs with active VMs. **Admin only** (P4d) — lists VMs across
    all users; the per-job VM detail/lifecycle endpoints stay job-scoped
    under P4f.

    Works from the database (no NATS required) — reads the 'vm' key from
    each job's context JSONB column.
    """
    await _require_admin(request)
    try:
        async with postgres_db.acquire() as conn:
            rows = await conn.fetch(
                "SELECT id, description, status, context->'vm' as vm_context "
                "FROM jobs WHERE context ? 'vm' "
                "ORDER BY updated_at DESC"
            )
        return [
            {
                "job_id": str(row["id"]),
                "description": row["description"],
                "job_status": row["status"],
                "vm": json.loads(row["vm_context"]) if row["vm_context"] else {},
            }
            for row in rows
        ]
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/vms/{job_id}")
async def get_vm_status(
    request: Request,
    job_id: str,
    live: bool = Query(False, description="Query live status via NATS request/reply"),
) -> dict[str, Any]:
    """Get VM status for a job.

    **P4f** — gated by `require_job_access`. VM status leaks pod/IP/host
    details, so caller must already be able to see the job.

    By default reads from the database. With ?live=true, also queries the VM
    controller via NATS request/reply for real-time status.
    """
    _, job = await require_job_access(request, postgres_db, job_id)

    context = job.get("context") or {}
    vm_ctx = context.get("vm") if isinstance(context, dict) else None
    if not vm_ctx:
        raise HTTPException(status_code=404, detail=f"No VM context for job '{job_id}'")

    result: dict[str, Any] = {"job_id": job_id, "vm": vm_ctx}

    if live:
        if not vm_provisioner.lifecycle_available:
            result["live_error"] = "VM provisioning not available"
        else:
            live_status = await vm_provisioner.query_status(job_id)
            if live_status:
                result["live"] = live_status
            else:
                result["live_error"] = "No response from VM controller"

    return result


@app.delete("/api/vms/{job_id}")
async def delete_vm(request: Request, job_id: str) -> dict[str, str]:
    """Delete a VM for a job.

    **P4f** — destructive. Caller must own the job OR be project-owner OR
    admin (mirrors `DELETE /api/jobs/{job_id}` from P4c). Plain project
    membership isn't enough.

    Uses NATS (cross-cluster) or direct Kubernetes API (same-cluster).
    Returns 503 if no VM provisioning backend is available.
    """
    caller, job = await require_job_access(request, postgres_db, job_id)
    if not caller.get("is_admin"):
        is_job_owner = str(job.get("user_id") or "") == str(caller["id"])
        is_project_owner = False
        if not is_job_owner and job.get("project_id"):
            role = await postgres_db.get_user_role_in_project(
                str(job["project_id"]), str(caller["id"])
            )
            is_project_owner = role == "owner"
        if not (is_job_owner or is_project_owner):
            raise HTTPException(
                status_code=403,
                detail="Only the job owner, the project owner, or an admin may delete this VM",
            )

    if not vm_provisioner.lifecycle_available:
        raise HTTPException(
            status_code=503, detail="VM provisioning not available (no NATS or K8s)"
        )

    success = await vm_provisioner.delete_vm(job_id)
    if not success:
        raise HTTPException(status_code=500, detail="Failed to delete VM")

    return {"status": "deleting", "job_id": job_id}


